cd /workspace && node -e "
const fs = require('fs');
const lines = fs.readFileSync('data/sales_q3.csv','utf8').trim().split('\n');
const header = lines[0].split(',');
const rows = lines.slice(1).map(l => {
  const c = l.split(',');
  return { region: c[2], amount: parseFloat(c[4]), status: c[6] };
});

let won=0, lost=0, pending=0, totalRevenue=0;
const dealsByRegion = {}, revByRegion = {};
for (const r of rows) {
  dealsByRegion[r.region] = (dealsByRegion[r.region]||0) + 1;
  if (r.status==='won') { won++; totalRevenue+=r.amount; revByRegion[r.region]=(revByRegion[r.region]||0)+r.amount; }
  else if (r.status==='lost') lost++;
  else pending++;
}
const total = won+lost+pending;
const winRate = total ? (won/total*100).toFixed(1) : '0.0';

const fmt = n => n.toLocaleString('en-US',{maximumFractionDigits:0});
const out = [];
out.push('='.repeat(45));
out.push('  Meridian Analytics — Q3 Sales Summary');
out.push('='.repeat(45));
out.push('  Total deals worked : ' + total);
out.push('  Won                : ' + won);
out.push('  Lost               : ' + lost);
out.push('  Pending            : ' + pending);
out.push('  Win rate           : ' + winRate + '%');
out.push('  Total revenue (won): \$' + fmt(totalRevenue));
out.push('');
out.push('  Revenue by region (won deals):');
Object.entries(revByRegion).sort((a,b)=>b[1]-a[1]).forEach(([reg,rev])=>{
  out.push('    ' + reg.padEnd(8) + ' \$' + fmt(rev).padStart(10) + '  (' + dealsByRegion[reg] + ' deals total)');
});
out.push('='.repeat(45));
fs.writeFileSync('sales_summary.txt', out.join('\n') + '\n');
console.log('Done. Output written to sales_summary.txt');
"
